using System.Collections.Generic;
using UnityEngine;
namespace MassiveArmy.Planetary {
    public sealed partial class PlanetRtsBase {
        public const int MaximumDetailedBuildings=4;
        readonly List<ModularBuildingDetail> modularDetails=new List<ModularBuildingDetail>();
        readonly BuildingView[] nearestModular=new BuildingView[MaximumDetailedBuildings];readonly float[] modularDistance=new float[MaximumDetailedBuildings];int modularFrame=-1;bool hasModular;
        public int DetailedModularBuildings {get{int count=0;foreach(var detail in modularDetails)if(detail.Building!=null)count++;return count;}}
        ModularBuildingDetail DetailFor(RtsBuilding building){foreach(var detail in modularDetails)if(detail.Building==building)return detail;return null;}
        public int VisibleModularRooms {get;private set;}
        void UpdateModularViews(){
            if(!hasModular||fixture.View==null||modularFrame==Time.frameCount)return;modularFrame=Time.frameCount;var camera=fixture.View;var eye=camera.transform.position;var eyeCell=Grid.Cell((eye-fixture.PlanetRenderCentre).normalized);
            for(int i=0;i<MaximumDetailedBuildings;i++){nearestModular[i]=null;modularDistance[i]=float.MaxValue;}
            foreach(var state in buildingViews){if(state.modular==null||state.building.removed||!state.building.Complete)continue;float reach=Mathf.Max((state.visible&&state.lod==0?state.modular.detailDistance:15)+state.detailRadius,state.plotRadius+16);if((state.pose.renderedPosition-eye).sqrMagnitude>reach*reach)continue;
                bool onPlot=Area(state.building).Contains(eyeCell);var local=state.root.InverseTransformPoint(eye);float distance=onPlot?-1:state.modular.bounds.SqrDistance(local);if(!onPlot&&(distance>state.modular.detailDistance*state.modular.detailDistance||!(state.visible&&state.lod==0)&&distance>15*15))continue;
                for(int slot=0;slot<MaximumDetailedBuildings;slot++)if(distance<modularDistance[slot]){for(int j=MaximumDetailedBuildings-1;j>slot;j--){nearestModular[j]=nearestModular[j-1];modularDistance[j]=modularDistance[j-1];}nearestModular[slot]=state;modularDistance[slot]=distance;break;}}
            foreach(var detail in modularDetails){bool wanted=false;for(int i=0;i<MaximumDetailedBuildings;i++)if(nearestModular[i]?.building==detail.Building&&detail.Building!=null)wanted=true;if(!wanted)detail.Release();}
            int created=0;for(int i=0;i<MaximumDetailedBuildings;i++){var state=nearestModular[i];if(state==null)continue;var detail=DetailFor(state.building);if(detail==null&&created==0){detail=DetailFor(null);if(detail==null&&modularDetails.Count<MaximumDetailedBuildings){detail=new ModularBuildingDetail();modularDetails.Add(detail);}if(detail!=null){detail.Bind(state.building,state.modular,surface,fixture);created++;}}}
            VisibleModularRooms=0;foreach(var detail in modularDetails)if(detail.Building!=null){detail.RefreshTerrain(surface,fixture);detail.Update(camera);VisibleModularRooms+=detail.VisibleRooms;}
            foreach(var state in buildingViews)if(state.modular!=null&&state.shell!=null&&state.lod==0){bool detailed=false;foreach(var detail in modularDetails)if(detail.Building==state.building){detailed=true;break;}var mesh=detailed?state.near:state.far;if(state.shell.sharedMesh!=mesh)state.shell.sharedMesh=mesh;}
        }
        public bool InteractModularDoor(Ray ray){foreach(var detail in modularDetails)if(detail.Interact(ray)){foreach(var colony in Settlements)if(colony!=null){var installation=SettlementLogistics.Find(colony,detail.Building.persistentId);if(installation!=null)installation.modularDoors=detail.Building.modularDoors;}Notice="Building door toggled · F to interact";return true;}return false;}
        internal void ValidateModularDetail(System.Action<bool,string> check,System.Action<string> capture=null){
            RtsBuilding building=null;foreach(var candidate in Buildings)if(candidate.definition.id=="civil_housing"&&art.FindBuilding(candidate.definition)?.modular!=null){building=candidate;break;}
            if(building==null)return;var layout=art.FindBuilding(building.definition).modular;var portal=System.Array.Find(layout.portals,p=>p.b<0&&!p.window);var transform=building.visual.transform;var camera=fixture.View;var originalPosition=camera.transform.position;var originalRotation=camera.transform.rotation;uint oldDoors=building.modularDoors;
            var area=Area(building);var up=Grid.Centre(area);float plane=FoundationRadius(building);bool level=true,above=true;
            for(int y=0;y<=8;y++)for(int x=0;x<=8;x++){var direction=Grid.Point(area,x/8f,y/8f);var point=PlotPoint(building,direction);level&=Mathf.Abs(Vector3.Dot(point,up)-plane)<.04f;above&=point.magnitude+.04f>=fixture.definition.radius+surface.SampleHeight(direction);}
            check(level,"Modular foundation is a level tangent plane across the plot");check(above,"Foundation covers sampled ground across the plot, including curvature");
            int joined=0;foreach(var connected in Buildings)if(!connected.removed&&PlotEntrance(connected,out var a,out var b,out var c,out var d)){joined++;float connectedPlane=FoundationRadius(connected);var connectedUp=Grid.Centre(Area(connected));if(IsModularBuilding(connected))check(Mathf.Abs(Vector3.Dot(a,connectedUp)-(connectedPlane-.02f))<.04f&&Mathf.Abs(Vector3.Dot(b,connectedUp)-(connectedPlane-.02f))<.04f,"Connected modular driveway shares its plot plane");check(Mathf.Abs(c.magnitude-(fixture.definition.radius+surface.SampleHeight(c.normalized)+.13f))<.04f&&Mathf.Abs(d.magnitude-(fixture.definition.radius+surface.SampleHeight(d.normalized)+.13f))<.04f,"Connected driveway terminates on the adjoining road surface");}
            check(joined>0,"Starting settlement exercises actual connected plot driveways");
            if(PlotEntrance(building,out var pa,out var pb,out var pc,out var pd)){check(Mathf.Abs(Vector3.Dot(pa,up)-(plane-.02f))<.04f&&Mathf.Abs(Vector3.Dot(pb,up)-(plane-.02f))<.04f,"Driveway joins the level plot edge");check(Mathf.Abs(pc.magnitude-(fixture.definition.radius+surface.SampleHeight(pc.normalized)+.13f))<.04f&&Mathf.Abs(pd.magnitude-(fixture.definition.radius+surface.SampleHeight(pd.normalized)+.13f))<.04f,"Driveway reaches the adjoining terrain road");}
            try{building.modularDoors=0;camera.transform.SetPositionAndRotation(transform.TransformPoint(portal.bounds.center+portal.normal*2),transform.rotation*Quaternion.LookRotation(-portal.normal));UpdateBuildingViews();modularFrame=-1;UpdateModularViews();Physics.SyncTransforms();var detail=DetailFor(building);
                check(detail!=null&&DetailedModularBuildings<=MaximumDetailedBuildings,"Near building streams into the bounded interior pool");check(!building.visual.GetComponent<BoxCollider>().enabled,"Detailed collision replaces the solid bounding collider");
                var walkPoint=PlotPoint(building,Grid.Point(area,.08f,.08f),-.04f)+fixture.PlanetRenderCentre;
                check(Physics.Raycast(walkPoint+up*2,-up,out var plotHit,3)&&plotHit.transform.IsChildOf(transform),"Level plot supplies nearby walking collision outside the building shell");
                var ray=new Ray(camera.transform.position,camera.transform.forward);check(Physics.Raycast(ray,out var closed,2.2f)&&closed.transform.IsChildOf(transform),"Closed entrance door blocks the player ray");check(InteractModularDoor(ray),"F interaction opens the real building entrance");Physics.SyncTransforms();check((building.modularDoors&(1u<<portal.door))!=0,"Door state is retained by the building");check(!Physics.Raycast(ray,out _,2.2f),"Open doorway is physically clear");detail.Update(camera);check(detail.VisibleRooms>0,"Open doorway exposes portal-visible rooms");
                check(detail.Layout==layout,"Interior uses shared baked layout assets");capture?.Invoke("ModularEntrance");camera.transform.position=transform.TransformPoint(new Vector3(11,7,layout.bounds.extents.z+13));camera.transform.LookAt(transform.TransformPoint(new Vector3(0,2,0)),transform.up);detail.Update(camera);capture?.Invoke("ModularExterior");if(capture!=null){var sun=fixture.LightingForValidation.Sun;var savedSun=sun.transform.rotation;try{sun.transform.rotation=Quaternion.LookRotation(up,Mathf.Abs(up.y)<.95f?Vector3.up:Vector3.right);fixture.LightingForValidation.Update();capture("ModularNight");}finally{sun.transform.rotation=savedSun;fixture.LightingForValidation.Update();}}camera.transform.SetPositionAndRotation(transform.TransformPoint(new Vector3(.85f,1.7f,portal.bounds.center.z-1.5f)),transform.rotation*Quaternion.LookRotation(-portal.normal));detail.Update(camera);capture?.Invoke("ModularHall");
            }finally{building.modularDoors=oldDoors;camera.transform.SetPositionAndRotation(originalPosition,originalRotation);modularFrame=-1;UpdateBuildingViews();UpdateModularViews();}
        }
        internal bool IsModularBuilding(RtsBuilding building)=>art.FindBuilding(building.definition)?.modular!=null;
    }
}
